let _epfP=null;
function ensurePaymentsFull(){
 if(window.FB&&FB._pagosFull)return Promise.resolve();
 if(_epfP)return _epfP;
 _epfP=(async()=>{
  try{
   toast("Cargando historial…");
   const P=await FB.loadAllPayments();
   if(Array.isArray(P)){
    const have=new Set(db.payments.map(p=>p.id));
    P.forEach(p=>{if(p&&p.id&&!have.has(p.id))db.payments.push(p)});
   }
  }catch(e){toast("No se pudo cargar el historial");throw e}
  finally{_epfP=null}
 })();
 return _epfP;
}
async function go(v){
 if((v==="historial"||v==="resumen")&&window.FB&&!FB._pagosFull){
  try{await ensurePaymentsFull()}catch(e){return}
 }
 view=v;if(v==="historial")hn=80;render();window.scrollTo(0,0)
}

