function clearErrors(fm){fm.querySelectorAll(".field-error").forEach(x=>x.remove());fm.querySelectorAll(".invalid").forEach(x=>x.classList.remove("invalid"))}
function fieldError(input,msg){if(!input)return;input.classList.add("invalid");const d=document.createElement("div");d.className="field-error";d.textContent=msg;input.insertAdjacentElement("afterend",d)}
function finishValidation(fm,items){clearErrors(fm);let first=null;for(const [el,msg] of items){if(!el||!msg)continue;fieldError(el,msg);if(!first)first=el}if(first){first.scrollIntoView({behavior:"smooth",block:"center"});first.focus({preventScroll:true});return false}return true}
