const NOMBRES=["Juan","María","Carlos","Ana","Luis","Carmen","José","Rosa","Pedro","Lucía","Miguel","Sofía","Francisco","Elena","Rafael","Patricia","Antonio","Laura","Manuel","Andrea","David","Mónica","Javier","Sandra","Ricardo","Diana","Fernando","Claudia","Roberto","Gabriela","Héctor","Valeria","Andrés","Paola","Óscar","Natalia","Eduardo","Verónica","Sergio","Julia"];
const APELLIDOS=["Pérez","Rodríguez","Gómez","Fernández","López","Martínez","Sánchez","Ramírez","Torres","Díaz","Hernández","Morales","Castro","Ortiz","Ruiz","Jiménez","Vargas","Mendoza","Rojas","Guerrero","Silva","Romero","Núñez","Cruz","Flores","Reyes","Medina","Aguilar","Castillo","Vega"];
const REFS=["Colmado La Esquina","Frente al parque","Calle 5","Cerca de la iglesia","Barrio Norte","Sector Los Almendros","Apartamento 3B","Casa azul","Al lado del colmado","Frente a la escuela","Calle Duarte","Residencial El Sol","Villa Mella","Los Mina","Herrera"];
const FREQS=["diario","semanal","quincenal","mensual"];
function rand(a,b){return a+Math.floor(Math.random()*(b-a+1))}
function pick(arr){return arr[Math.floor(Math.random()*arr.length)]}
async function cargaPrueba(){
 if(locked())return toast("Membresía vencida: solo lectura");
 const n=500;
 confirmBox(`Se crearán <b>${n} clientes</b> con 3–5 préstamos cada uno (~1.500–2.500 préstamos).<br><br>Puede tardar 1–3 minutos en subirse a Firebase. ¿Continuar?`,async()=>{
  openModal(`<h2>Generando datos de prueba…</h2><p class="mt" id="cp-status">Creando clientes en memoria…</p><div class="live" id="cp-live"><div><span>Clientes</span><b id="cp-c">0</b></div><div><span>Préstamos</span><b id="cp-l">0</b></div></div>`);
  const t0=performance.now(),t=today(),freqs=FREQS;
  let addedC=0,addedL=0;
  try{
   for(let i=0;i<n;i++){
    const name=pick(NOMBRES)+" "+pick(APELLIDOS)+(Math.random()<.3?" "+pick(APELLIDOS):"");
    const phone="8"+pick(["09","29","49"])+String(rand(1000000,9999999));
    const c={id:uid(),name,phone,ref:pick(REFS),note:"carga-prueba"};
    db.clients.push(c);addedC++;
    const nLoans=rand(3,5);
    for(let j=0;j<nLoans;j++){
     const cap=rand(10,80)*100;
     const isC=Math.random()<.45;
     const freq=pick(freqs);
     const ln=isC
      ?{t:"c",cap,pct:rand(10,30),n:rand(2,12),freq,date:addDays(t,-rand(0,40)),wd:rand(0,6)}
      :{t:"r",cap,fee:r2(cap*rand(5,15)/100),freq,date:addDays(t,-rand(0,40)),wd:rand(0,6)};
     newLoan(c.id,ln,"carga-prueba");
     const L=db.loans[db.loans.length-1];
     L.nextDate=addDays(t,rand(-10,20));
     addedL++;
    }
    if((i+1)%50===0||i===n-1){
     const sc=$("#cp-c"),sl=$("#cp-l"),st=$("#cp-status");
     if(sc)sc.textContent=String(addedC);if(sl)sl.textContent=String(addedL);
     if(st)st.textContent=`En memoria: ${addedC} clientes, ${addedL} préstamos…`;
     await new Promise(r=>setTimeout(r,0));
    }
  }
   const tMem=performance.now();
   const st=$("#cp-status");if(st)st.textContent=`Subiendo a Firebase (guardado optimizado, sin releer todo)…`;
   /* Forzar guardado inmediato (sin debounce) */
   if(window.FB){
    await FB.saveData(JSON.stringify(db));
   }
   const tEnd=performance.now();
   render();
   openModal(`<h2>Carga de prueba lista</h2>
    <p class="mt">Se crearon <b>${addedC} clientes</b> y <b>${addedL} préstamos</b>.</p>
    <div class="live">
     <div><span>Tiempo en memoria</span><b>${Math.round(tMem-t0)} ms</b></div>
     <div><span>Tiempo subida Firebase</span><b>${Math.round(tEnd-tMem)} ms</b></div>
     <div><span>Total</span><b>${Math.round(tEnd-t0)} ms</b></div>
     <div><span>Modo de guardado</span><b>delta (sin getDocs previos)</b></div>
    </div>
    <p class="mt" style="margin-top:10px">Ahora prueba cobrar, editar o abrir la app de nuevo y mira en la consola de Firebase cuántas lecturas/escrituras se generaron.</p>
    <div class="mf"><button class="btn" data-close>Entendido</button></div>`);
  }catch(e){
   console.error(e);
   openModal(`<h2>Error en la carga</h2><p class="mt">${esc(e&&e.message||String(e))}</p><div class="mf"><button class="btn" data-close>Cerrar</button></div>`);
  }
 },"Generar");
}
function borrarPrueba(){
 confirmBox("Se borrarán <b>todos</b> los clientes, préstamos y pagos de <b>esta cuenta de prueba</b>. No se puede deshacer.",async()=>{
  try{await ensurePaymentsFull()}catch(e){return}
  db=empty();
  save();
  render();
  toast("Datos de prueba borrados");
 },"Sí, borrar todo");
}

/* ===== MEMBRESÍA ===== */
const DAY=864e5,fmtd=t=>{const d=new Date(t);return pad(d.getDate())+"/"+pad(d.getMonth()+1)+"/"+d.getFullYear()};
function mem(){const m=(window.FB&&FB.me)||{},n=Date.now(),c=m.createdAt||n,dl=x=>Math.max(1,Math.ceil((x-n)/DAY));
 if(m.blocked)return{s:"locked"};
 if(m.exempt||(m.exemptUntil&&n<m.exemptUntil))return{s:"exempt"};
 const t=c+15*DAY,p=m.paidUntil||0;
 if(n<p)return{s:"paid",d:dl(p),u:p};
 if(n<t)return{s:"trial",d:dl(t)};
 if(p&&n<p+5*DAY)return{s:"grace",d:dl(p+5*DAY)};
 return{s:"locked"}}
/* Bloqueo por membresía: modo solo lectura cuando está vencida (el servidor también lo exige en las reglas) */
const locked=()=>mem().s==="locked";
const dd=n=>n+(n===1?" día":" días");
function memText(){const m=mem();return{exempt:"Membresía: exonerada",paid:"Membresía activa hasta "+(m.u?fmtd(m.u):""),trial:"Prueba gratis: "+(m.d?dd(m.d):"")+" restantes",grace:"Membresía vencida: te quedan "+(m.d?dd(m.d):""),locked:"Membresía vencida: modo solo lectura"}[m.s]}
function pendBanner(){const m=(window.FB&&FB.me)||{};return m.pending&&["paid","exempt"].indexOf(mem().s)<0?`<div class="mb"><span>⏳ Comprobante enviado. Estamos verificando tu pago.</span></div>`:""}
function announcement(){const a=(_cfg&&_cfg.announcement)||{},seen=(window.FB&&FB.me&&FB.me.announcementSeen)||"";if(!a.id||!a.title||!a.message||seen===String(a.id))return"";return`<div class="announcement"><button class="ax" data-a="cerrarActualizacion" aria-label="Cerrar actualización">×</button><div class="at">${esc(a.title)}</div><div class="am">${esc(a.message)}</div></div>`}
function banner(){return pendBanner()+mbanner()}
function mbanner(){const m=mem();let t,c;
 if(m.s==="trial"){t="Prueba gratis: "+(m.d===1?"te queda 1 día":"te quedan "+m.d+" días");c=""}
 else if(m.s==="paid"&&m.d<=5){t="Tu membresía vence en "+dd(m.d);c="wn"}
 else if(m.s==="grace"){t="Membresía vencida. Te quedan "+dd(m.d)+" para renovar";c="er"}
 else if(m.s==="locked"){t="Membresía vencida: solo lectura";c="er"}
 else return"";
 return`<div class="mb ${c}"><span>${t}</span><button class="btn s" data-a="plan">${m.s==="trial"||m.s==="paid"?"Ver planes":"Pagar"}</button></div>`}
function roView(a,id){let c,l;if(a==="ver")c=db.clients.find(x=>x.id===id);else{l=db.loans.find(x=>x.id===id);c=l&&db.clients.find(x=>x.id===l.clientId)}
 if(!c)return;const ph=String(c.phone||"").replace(/\D/g,""),w=ph.length===10?"1"+ph:ph,
 txt=encodeURIComponent("Hola "+c.name+", te escribo para recordarte tu pago"+(l?" de "+money(balance(l)):"")+".");
 openModal(`<h2>${esc(c.name)}</h2><p class="mt">${esc(c.phone||"Sin teléfono")}</p>${l?`<p>Debe ${money(balance(l))}</p>`:""}<p class="mt" style="margin-top:10px">Modo solo lectura: renueva tu membresía para registrar cobros.</p><div class="mf"><button class="btn g" data-close>Cerrar</button>${w?`<a class="btn" href="https://wa.me/${w}?text=${txt}" target="_blank" rel="noopener">WhatsApp</a>`:""}</div>`)}
let _cfg=null,_plan="m";
const rdn=n=>"RD$"+(+n||0).toLocaleString("es-DO");
function PR(){const c=_cfg||{},m=+c.priceMonthly||500,y=+c.priceYearly||4800,me=(window.FB&&FB.me)||{},v=+me.discValue||0;
 if(me.discType==="pct"&&v>0)return{m:Math.round(m*(1-v/100)),y:Math.round(y*(1-v/100)),m0:m,y0:y};
 if(me.discType==="fix"&&v>0)return{m:v,y:Math.round(y*v/m),m0:m,y0:y};
 return{m,y,m0:m,y0:y}}
async function planFlow(){openModal('<p class="mt">Cargando…</p>');try{await FB.refresh();_cfg=await FB.getConfig()}catch(e){}
 if(!locked()||true)planStep1()}
function planStep1(){const p=PR(),sv=Math.round((1-p.y0/(12*p.m0))*100),
 opt=(k,l,pr,pr0,sub)=>`<label class="pl${_plan===k?" on":""}"><input type="radio" name="pl" value="${k}" ${_plan===k?"checked":""}><div><b>${l}</b><div class="mt">${sub}</div></div><div style="text-align:right">${pr<pr0?`<s class="mt">${rdn(pr0)}</s><br>`:""}<b>${rdn(pr)}</b></div></label>`;
 openModal(`<h2>Pagar membresía</h2><p class="mt" style="margin-bottom:10px">Elige tu plan</p>${opt("m","Mensual",p.m,p.m0,"Cada mes")}${opt("y","Anual",p.y,p.y0,sv>0?"Ahorras "+sv+"%":"Cada año")}<div class="mf"><button class="btn g" data-close>Cancelar</button><button class="btn" id="pn">Siguiente</button></div>`);
 document.querySelectorAll("input[name=pl]").forEach(i=>i.onchange=()=>{_plan=i.value;planStep1()});
 $("#pn").onclick=planStep2}
function planStep2(){const c=_cfg||{},p=PR(),amt=_plan==="m"?p.m:p.y,me=FB.me||{},b=c.bank||{},nm=_plan==="m"?"mensual":"anual",w=String(c.whatsapp||"").replace(/\D/g,""),
 msg=encodeURIComponent("*Hola, soy "+me.name+".*\n\nMi código: *"+me.code+".*\n\nPagué la Membresía RutaCobro.\nPlan "+nm+", "+rdn(amt)+".\nAdjunto el comprobante."),
 row=(l,v)=>v?`<div class="bk"><div><div class="mt">${l}</div><b>${esc(v)}</b></div>${l==="Número de cuenta"?`<button class="btn g s" data-copy="${esc(v)}">Copiar</button>`:""}</div>`:"";
 openModal(`<h2>Transferencia</h2><p class="mt">Plan ${nm}: <b style="color:var(--tx)">${rdn(amt)}</b></p>${b.number&&w?`<p class="mt" style="margin:8px 0">El pago se realiza por transferencia. Hazla en tu banco o en la sucursal más cercana a esta cuenta:</p>${row("Banco",b.name)}${row("Titular",b.holder)}${row("Tipo de cuenta",b.type)}${row("Número de cuenta",b.number)}<p class="mt" style="margin:8px 0">Luego envía la foto del comprobante por WhatsApp.</p><div class="mf"><button class="btn g" id="pb">Atrás</button><a class="btn" href="https://wa.me/${w}?text=${msg}" target="_blank" rel="noopener" id="pw">Enviar comprobante por WhatsApp</a></div>`:`<p style="margin:10px 0">Los datos de pago aún no están disponibles. Intenta más tarde.</p><div class="mf"><button class="btn g" id="pb">Atrás</button></div>`}`);
 $("#pb").onclick=planStep1;
 const pw=$("#pw");if(pw)pw.onclick=()=>setTimeout(()=>{FB.setPending(_plan,amt).catch(()=>{});closeModal();view="hoy";window.scrollTo(0,0);render();toast("Comprobante enviado. Verificaremos tu pago.")},400);
 document.querySelectorAll("[data-copy]").forEach(x=>x.onclick=()=>{try{navigator.clipboard.writeText(x.dataset.copy).then(()=>toast("Copiado"))}catch(e){toast("No se pudo copiar")}})}
async function supportFlow(){openModal('<p class="mt">Cargando…</p>');let ms=[];
 try{const r=await Promise.all([FB.getConfig(),FB.myMessages()]);_cfg=r[0];ms=r[1]}catch(e){}
 const w=String((_cfg||{}).whatsapp||"").replace(/\D/g,""),me=FB.me||{},SL={nuevo:"Enviado",leido:"Leído",resuelto:"Resuelto"},
 urg=w?`<a class="btn g" href="https://wa.me/${w}?text=${encodeURIComponent("*URGENTE.* Soy "+me.name+", código *"+me.code+".*\n\n")}" target="_blank" rel="noopener">Urgente: escribir por WhatsApp</a>`:"";
 openModal(`<h2>Soporte</h2><p class="mt">Cuéntanos tu queja, duda o sugerencia.</p><textarea id="sm" maxlength="1000" placeholder="Escribe tu mensaje"></textarea><div class="mf"><button class="btn g" data-close>Cerrar</button><button class="btn" id="ss">Enviar</button></div><div style="margin-top:8px">${urg}</div>${ms.length?`<h2 style="margin-top:16px">Tus mensajes</h2>${ms.map(m=>`<div class="sm"><div class="mt">${fmtd(m.t)} · ${SL[m.status]||"Enviado"}</div><div>${esc(m.text)}</div>${m.reply?`<div class="rp"><div class="mt">Respuesta de soporte</div>${esc(m.reply)}</div>`:""}</div>`).join("")}`:""}`);
 $("#ss").onclick=()=>{const t=$("#sm").value.trim();if(!t)return toast("Escribe tu mensaje");$("#ss").disabled=true;
  FB.sendMessage(t).then(()=>{toast("Mensaje enviado");supportFlow()}).catch(()=>{toast("No se pudo enviar. Intenta de nuevo");$("#ss").disabled=false})}}
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&window.FB&&FB.user&&FB.me)FB.refresh().then(()=>FB.getConfig()).then(c=>{_cfg=c;render()}).catch(()=>{})});

/* ===== ELIMINAR COBRO (mantener pulsado en el historial) ===== */
let _lpT=null,_lpX=0,_lpY=0,_lpAt=0;
function lpCancel(){clearTimeout(_lpT);_lpT=null}
function lpOpen(pid){const n=Date.now();if(n-_lpAt<1200)return;_lpAt=n;try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}eliminarCobro(pid)}
document.addEventListener("pointerdown",e=>{const r=e.target.closest("[data-pid]");if(!r||e.target.closest("button,a"))return;_lpX=e.clientX;_lpY=e.clientY;lpCancel();_lpT=setTimeout(()=>{_lpT=null;lpOpen(r.dataset.pid)},600)});
document.addEventListener("pointermove",e=>{if(_lpT&&(Math.abs(e.clientX-_lpX)>10||Math.abs(e.clientY-_lpY)>10))lpCancel()});
["pointerup","pointercancel"].forEach(t=>document.addEventListener(t,lpCancel));
document.addEventListener("scroll",lpCancel,true);
document.addEventListener("contextmenu",e=>{const r=e.target.closest("[data-pid]");if(!r)return;e.preventDefault();lpCancel();lpOpen(r.dataset.pid)});
async function eliminarCobro(pid){
 if(locked())return toast("Membresía vencida: solo lectura");
 const fromClient=!!document.querySelector("#md .client-view"),p=db.payments.find(x=>x.id===pid);if(!p)return;
 if(window.FB&&!FB._pagosFull){try{const extra=await FB.loadClientPayments(p.clientId);if(Array.isArray(extra)){const have=new Set(db.payments.map(x=>x.id));extra.forEach(x=>{if(x&&x.id&&!have.has(x.id))db.payments.push(x)})}}catch(e){return toast("No se pudo cargar el historial. Revisa tu conexión")}}
 const l=loan(p.loanId),back=()=>fromClient?ver(p.clientId):closeModal(),
  info=t=>{openModal(`<h2>Eliminar cobro</h2><p class="mt" style="margin:8px 0">${t}</p><div class="mf"><button type="button" class="btn" id="eb">Entendido</button></div>`);$("#eb").onclick=back};
 if(p.renewal)return info("Las renovaciones no se eliminan desde aquí. Para deshacer una renovación, elimina el préstamo nuevo desde la ficha del cliente.");
 if(!l)return info("No se encontró el préstamo de este cobro.");
 if(l.renewed)return info("Este préstamo ya fue renovado, así que sus cobros no se pueden eliminar.");
 if(!p.pre)return info("Este cobro es anterior a esta función y no se puede eliminar automáticamente.");
 if(db.payments.some(x=>x.loanId===l.id&&!x.renewal&&x.id!==p.id&&x.id>p.id))return info("Solo se puede eliminar el último cobro de cada préstamo. Elimina primero los cobros más recientes de este préstamo.");
 if(Math.abs(balance(l)-(p.bal||0))>EPS||(isDone(l)?"":l.nextDate)!==(p.next||""))return info("Este préstamo se editó después del cobro, así que no se puede eliminar automáticamente.");
 const c=client(p.clientId);
 openModal(`<h2>Eliminar cobro</h2><div class="sm"><div><b>${esc(c?c.name:"(eliminado)")}</b></div><div class="mt">${fdate(p.date)} · ${concept(p)}</div><div style="margin-top:4px"><b>${money(p.interest+p.capital)}</b></div></div><p class="mt" style="margin:8px 0">El préstamo volverá a como estaba antes de este cobro (deuda y fecha de pago). Si fue un error, después puedes registrar el cobro bien.</p><label>Escribe <b>eliminar</b> para confirmar</label><input id="ec" autocomplete="off" autocapitalize="off" spellcheck="false"><div class="mf"><button type="button" class="btn g" id="en">Cancelar</button><button type="button" class="btn d" id="ex" disabled>Eliminar cobro</button></div>`);
 const inp=$("#ec"),ex=$("#ex");
 inp.oninput=()=>{ex.disabled=nrm(inp.value)!=="eliminar"};
 $("#en").onclick=back;
 ex.onclick=()=>{if(nrm(inp.value)!=="eliminar")return;
  Object.keys(l).forEach(k=>delete l[k]);Object.assign(l,JSON.parse(JSON.stringify(p.pre)));
  db.payments=db.payments.filter(x=>x.id!==p.id);
  save();render();toast("Cobro eliminado");back()};
}

